<?php
declare(strict_types=1);
require dirname(__DIR__) . '/bootstrap.php';
use Baize\{Analytics, Annotations, App, Database, External, Governance, Http, HttpError, Operations, Router, Security, Store};

$port = (int)(getenv('BAIZE_TEST_DB_PORT') ?: 3307); $name = 'baize_annotations_' . bin2hex(random_bytes(4));
$server = new PDO("mysql:host=127.0.0.1;port=$port;charset=utf8mb4", 'root', '', [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]); $server->exec("CREATE DATABASE `$name` CHARACTER SET utf8mb4 COLLATE utf8mb4_bin");
$directory = sys_get_temp_dir() . '/' . $name; mkdir($directory, 0700); $checks = 0;
$assert = static function(bool $ok, string $why) use (&$checks): void { $checks++; if (!$ok) throw new RuntimeException($why); };
$equal = static function(mixed $a, mixed $b, string $why) use ($assert): void { $assert($a === $b, $why . ': ' . json_encode($a, JSON_UNESCAPED_UNICODE) . ' !== ' . json_encode($b, JSON_UNESCAPED_UNICODE)); };
try {
    $db = new Database(['dsn' => "mysql:host=127.0.0.1;port=$port;dbname=$name;charset=utf8mb4", 'user' => 'root', 'password' => '']); $db->migrate();
    $config = ['public_url' => 'https://analytics.example.test', 'data_dir' => $directory, 'key_dir' => $directory, 'master_key' => random_bytes(32)]; $app = new App($config, $db); $router = new Router(); Annotations::register($app, $router); Governance::configure($config);
    $site = ['id' => 'notes', 'domain' => 'example.test', 'name' => 'Notes', 'timezone' => 'Asia/Shanghai', 'retention_days' => 365, 'privacy_mode' => 'standard', 'created_at' => Store::now(), 'salt_secret' => 'notes-secret', 'config' => []]; $app->store->put('sites', 'notes', $site, 'notes'); $app->store->put('sites', 'other', array_replace($site, ['id' => 'other']), 'other');
    $headers = [];
    foreach (['owner' => 'owner', 'viewer' => 'viewer', 'analyst' => 'analyst'] as $id => $role) { $app->store->put('users', $id, ['id' => $id, 'email' => $id . '@example.test', 'is_admin' => false]); $app->store->put('site_members', 'notes:' . $id, ['site_id' => 'notes', 'user_id' => $id, 'role' => $role], 'notes'); $token = str_repeat(substr($id, 0, 1), 32); $app->store->put('api_tokens', $id, ['id' => $id, 'user_id' => $id, 'site_id' => 'notes', 'token_hash' => Security::hashToken($token), 'scopes' => ['read', 'write']], 'notes'); $headers[$id] = ['authorization' => 'Bearer ' . $token]; }
    $dispatch = static function(string $method, string $suffix = '', array $body = [], array $query = [], string $user = 'owner') use ($router, $headers): mixed { return $router->dispatch(new Http($method, '/api/v1/sites/notes/annotations' . $suffix, $body, $headers[$user], $query)); };
    $denied = static function(callable $fn, string $code) use ($equal): void { try { $fn(); throw new RuntimeException('Expected ' . $code); } catch (HttpError $error) { $equal($error->errorCode, $code, 'rejected invalid or unauthorized note action'); } };
    $today = (new DateTimeImmutable('today', new DateTimeZone('UTC')))->format('Y-m-d'); $window = ['from' => $today, 'to' => $today];
    $denied(static fn() => $router->dispatch(new Http('GET', '/api/v1/sites/notes/annotations', [], [], $window)), 'login_required');
    $before = Analytics::stats($app, 'notes'); $created = $dispatch('POST', '', ['date' => $today, 'title' => '　部署支付页面　', 'note' => "人工解释不是指标证据。\nmanual-note-private-body"]);
    $equal($created['origin'], 'manual_note', 'created note origin'); $equal($created['measuredEvidence'], false, 'created note never measured evidence');
    $read = $dispatch('GET', '', [], $window, 'viewer'); $equal(count($read['rows']), 1, 'viewer can read notes'); $equal($read['rows'][0]['title'], '部署支付页面', 'unicode surrounding whitespace trimmed'); $equal($read['rows'][0]['timezone'], 'Asia/Shanghai', 'creation snapshots current site timezone'); $equal($read['rows'][0]['note'], "人工解释不是指标证据。\nmanual-note-private-body", 'note preserves intentional newlines'); $equal($read['timezoneSemantics'], 'per_note_write_time_snapshot', 'timezone semantics explicit'); $assert(!$read['measuredEvidence'] && !$read['causalEvidence'], 'manual and causal status truthful'); $assert(!isset($read['rows'][0]['created_by']), 'read response excludes account identifier');
    $denied(static fn() => $dispatch('POST', '', ['date' => $today, 'title' => 'viewer cannot write'], [], 'viewer'), 'site_permission_denied');
    $denied(static fn() => $dispatch('PATCH', '/' . $created['id'], ['date' => $today, 'title' => 'viewer cannot edit'], [], 'viewer'), 'site_permission_denied');
    $denied(static fn() => $dispatch('DELETE', '/' . $created['id'], [], [], 'viewer'), 'site_permission_denied');
    $site['timezone'] = 'America/New_York'; $app->store->put('sites', 'notes', $site, 'notes'); $read = $dispatch('GET', '', [], $window); $equal($read['currentTimezone'], 'America/New_York', 'read exposes current site timezone'); $equal($read['rows'][0]['timezone'], 'Asia/Shanghai', 'changing site timezone does not rewrite old note dates');
    $dispatch('PATCH', '/' . $created['id'], ['date' => $today, 'title' => '更新支付页面', 'note' => 'manual-note-private-body'], [], 'analyst'); $read = $dispatch('GET', '', [], $window); $equal($read['rows'][0]['timezone'], 'America/New_York', 'edit snapshots write-time timezone'); $equal($read['rows'][0]['title'], '更新支付页面', 'analyst may edit notes');
    $stored = $app->store->get('annotations', $created['id']); $equal($stored['created_by'], 'owner', 'edit preserves original author');
    foreach ([['date' => '2026-02-30', 'title' => 'invalid'], ['date' => $today, 'title' => '   '], ['date' => $today, 'title' => str_repeat('字', 121)], ['date' => $today, 'title' => 'valid', 'note' => str_repeat('字', 2001)], ['date' => $today, 'title' => 'valid', 'note' => null], ['date' => $today, 'title' => 'valid', 'site_id' => 'other']] as $invalid) {
        try { $dispatch('POST', '', $invalid); $assert(false, 'invalid body should fail'); } catch (HttpError $error) { $equal($error->status, 400, 'strict note body bounds'); }
    }
    $denied(static fn() => $dispatch('PATCH', '/not-a-uuid', ['date' => $today, 'title' => 'invalid id']), 'annotation_id_invalid');
    $leap = $dispatch('POST', '', ['date' => '2024-02-29', 'title' => '闰日记录']); $equal($app->store->get('annotations', $leap['id'])['note'], '', 'optional note defaults to empty');
    $emoji = $dispatch('POST', '', ['date' => $today, 'title' => str_repeat('🐲', 60)]); $assert(isset($emoji['id']), 'title follows UTF16 length budget'); try { $dispatch('POST', '', ['date' => $today, 'title' => str_repeat('🐲', 61)]); $assert(false, 'emoji length should fail'); } catch (HttpError $error) { $equal($error->status, 400, 'UTF16 overlength rejected'); }
    foreach ([['from' => '2026-02-30', 'to' => '2026-03-01'], ['from' => '2026-01-01', 'to' => '2027-01-02'], ['from' => '2026-01-02', 'to' => '2026-01-01'], $window + ['site_id' => 'other']] as $invalid) { try { $dispatch('GET', '', [], $invalid); $assert(false, 'invalid date window should fail'); } catch (HttpError $error) { $equal($error->status, 400, 'annotation query bounds'); } }
    $foreign = Store::uuid(); $app->store->put('annotations', $foreign, ['id' => $foreign, 'site_id' => 'other', 'date' => $today, 'timezone' => 'UTC', 'title' => 'foreign', 'note' => 'private-other-site'], 'other');
    $denied(static fn() => $dispatch('PATCH', '/' . $foreign, ['date' => $today, 'title' => 'cross site']), 'annotation_missing'); $denied(static fn() => $dispatch('DELETE', '/' . $foreign), 'annotation_missing'); $assert(!str_contains(json_encode($dispatch('GET', '', [], $window)), 'private-other-site'), 'list remains scoped to authorized site');
    $after = Analytics::stats($app, 'notes'); $equal(json_encode($after['totals']), json_encode($before['totals']), 'manual notes do not create statistical events'); $equal($app->store->list('events', 'notes'), [], 'annotations never enter tracker event namespace');
    $evidence = External::evidence($app, 'notes', ['start' => $today, 'end' => $today]); $assert(!str_contains(json_encode($evidence), 'manual-note-private-body') && !isset($evidence['annotations']), 'manual notes excluded from AI evidence');
    $export = Operations::exportSite($app, 'notes', true); $assert(isset($export['tables']['annotations']), 'authorized full export preserves manual notes');
    Governance::deleteVisitor($app, 'notes', ['visitor_id' => 'unrelated-visitor'], 'owner'); $assert($app->store->get('annotations', $created['id']) !== null, 'visitor deletion preserves unrelated manual notes');
    $audit = $app->store->list('audit_logs', 'notes'); $actions = array_column($audit, 'action'); $assert(in_array('annotation.create', $actions, true) && in_array('annotation.update', $actions, true), 'annotation writes audited'); $assert(!str_contains(json_encode($audit), 'manual-note-private-body'), 'audit records omit note content');
    $dispatch('DELETE', '/' . $created['id']); $equal($app->store->get('annotations', $created['id']), null, 'note deleted'); $denied(static fn() => $dispatch('DELETE', '/' . $created['id']), 'annotation_missing'); $assert(in_array('annotation.delete', array_column($app->store->list('audit_logs', 'notes'), 'action'), true), 'delete audited');
    for ($i = 0; $i < 201; $i++) { $id = Store::uuid(); $app->store->put('annotations', $id, ['id' => $id, 'site_id' => 'notes', 'date' => $today, 'title' => '备注 ' . $i, 'note' => '', 'timezone' => 'America/New_York', 'created_at' => Store::now(), 'updated_at' => Store::now()], 'notes'); }
    $capped = $dispatch('GET', '', [], $window); $equal(count($capped['rows']), 200, 'bounded first 200 rows'); $equal($capped['truncated'], true, 'annotation truncation disclosed'); $ids = array_column($capped['rows'], 'id'); $sorted = $ids; sort($sorted); $equal($ids, $sorted, 'same-day records ordered deterministically by id');
    echo json_encode(['suite' => 'annotations', 'passed' => $checks, 'database' => $server->query('SELECT VERSION()')->fetchColumn()], JSON_UNESCAPED_UNICODE) . PHP_EOL;
} finally {
    $server->exec("DROP DATABASE `$name`"); $remove = static function(string $path) use (&$remove): void { if (is_dir($path)) { foreach (scandir($path) as $file) if ($file !== '.' && $file !== '..') $remove($path . '/' . $file); rmdir($path); } elseif (is_file($path)) unlink($path); }; $remove($directory);
}
